// S47 corpus: timeunit / timeprecision directives inside a module.
// Both the keyword-separated form (two statements) and the combined
// timeunit <unit> / <prec>; form are exercised here and in fifo_pkg.sv.
//
// S48 corpus: TypeParameterDeclaration — parameter type DATA_T = logic [7:0]
// exercises the single-assignment form with a default type.
module fifo
    import fifo_pkg::*;
#(
    parameter int DEPTH = 8,
    parameter int WIDTH = 32,
    parameter type DATA_T = logic [7:0]
) (
    input  logic              clk,
    input  logic              rst_n,
    input  logic              push,
    input  logic              pop,
    input  logic [WIDTH-1:0]  din,
    output logic [WIDTH-1:0]  dout,
    output logic              full,
    output logic              empty,
    output fifo_status_e      status
);

    timeunit 1ns;
    timeprecision 1ps;

    import fifo_pkg::FULL;
    // S50 corpus: multi-item PackageImportDeclaration — two PackageImportItem
    // children in one declaration, exercising the per-item imports_item edge.
    import fifo_pkg::EMPTY, fifo_pkg::NORMAL;

    logic [WIDTH-1:0] mem [DEPTH];
    logic [$clog2(DEPTH):0] wr_ptr;
    logic [$clog2(DEPTH):0] rd_ptr;
    logic [$clog2(DEPTH):0] count;

    function automatic logic [$clog2(DEPTH):0] next_ptr(logic [$clog2(DEPTH):0] p);
        next_ptr = p + 1'b1;
    endfunction

    assign full  = (count == DEPTH);
    assign empty = (count == 0);
    assign dout  = mem[rd_ptr[$clog2(DEPTH)-1:0]];

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            wr_ptr <= '0;
            rd_ptr <= '0;
            count  <= '0;
        end else begin
            if (push && !full) begin
                mem[wr_ptr[$clog2(DEPTH)-1:0]] <= din;
                wr_ptr <= next_ptr(wr_ptr);
            end
            if (pop && !empty) begin
                rd_ptr <= next_ptr(rd_ptr);
            end
            case ({push && !full, pop && !empty})
                2'b10: count <= count + 1'b1;
                2'b01: count <= count - 1'b1;
                default: count <= count;
            endcase
        end
    end

    always_comb begin
        if (full)        status = FULL;
        else if (empty)  status = EMPTY;
        else             status = NORMAL;
    end

endmodule

// S34 corpus: generic always @(...) blocks — non-FF, non-comb, non-latch.
// Two variants exercised:
//   1. always @(posedge clk) — edge-sensitive sensitivity list
//   2. always @(a or b)      — level-sensitive sensitivity list
module always_demo (
    input  logic clk,
    input  logic a,
    input  logic b,
    output logic q,
    output logic r
);
    // Variant 1: posedge-only (generic always, not always_ff)
    always @(posedge clk) begin
        q <= a;
    end

    // Variant 2: level-sensitive (a or b)
    always @(a or b) begin
        r = a & b;
    end
endmodule

// S35 corpus: always_latch block — inferred latch (no sensitivity list).
// Two signals exercised:
//   latch_out — driven when en is high, reads latch_in
//   latch_sel — driven from a conditional reading both latch_in and b
module latch_demo (
    input  logic en,
    input  logic latch_in,
    input  logic b,
    output logic latch_out,
    output logic latch_sel
);
    always_latch begin
        if (en) begin
            latch_out = latch_in;
            latch_sel = latch_in & b;
        end
    end
endmodule

// S38 corpus: genvar declaration (single and multi-identifier) + for-generate.
// Exercises:
//   genvar i;            — single genvar
//   genvar j, k;         — multi-genvar (two identifiers in one declaration)
//   for (i = 0; ...) begin : g_ent  — for-generate referencing i
module genvar_demo #(parameter int N = 4) ();
    genvar i;
    genvar j, k;
    for (i = 0; i < N; i = i + 1) begin : g_ent
    end
endmodule

// S44 corpus: DPI import declarations.
// Exercises the four key variants:
//   1. import "DPI-C" function int c_compute(input int x)  — function, DPI-C spec
//   2. import "DPI-C" task c_log(input int level)          — task, DPI-C spec
//   3. import "DPI" function void dpi_reset()              — function, DPI spec
//
// S45 corpus: DPI export declarations (export "DPI-C" function|task <name> ;).
// Two variants exercised:
//   1. export "DPI-C" function sv_compute  — re-exports a module-local SV function
//   2. export "DPI-C" task sv_task         — exports a task (resolves to _unresolved)
// sv_compute is defined as a regular SV function so the edge resolves via name_index.
// sv_task has no body in this scope so the edge emits _unresolved.sv_task.
module dpi_demo ();
    import "DPI-C" function int c_compute(input int x);
    import "DPI-C" task c_log(input int level);
    import "DPI" function void dpi_reset();

    function automatic int sv_compute(input int x);
        sv_compute = x * 2;
    endfunction

    export "DPI-C" function sv_compute;
    export "DPI-C" task sv_task;
endmodule

// S46 corpus: net alias declaration (bidirectional equivalence, SV §10.11).
// Three signals form one alias chain: alias a = b = c;
// Expected edges: a aliases b, b aliases c  (consecutive-pairs convention).
// The three logic declarations ensure name_index has entries for a, b, c.
module alias_demo;
    logic a, b, c;
    alias a = b = c;
endmodule

// S54 corpus: NetDeclaration variants exercising net_type and signing.
// Expected nodes:
//   - net_decl group nodes (one per NetDeclaration statement) carrying
//     {net_type, signed} attrs.
//   - role="net" Declarator children promoted under each group, plus
//     has_net edges to the enclosing module (same convention as S1).
module net_demo;
    wire nw;
    tri  nt;
    supply0 ng;
    wire signed [3:0] nss;
endmodule

// S84 corpus: UserDefinedNetDeclaration — a net declaration using a
// user-defined nettype together with a #(delay) value. The form is
// distinct from a plain NetDeclaration (S54) because pyslang parses
// ``<userType> #(<delay>) <decl>, ...`` as UserDefinedNetDeclarationSyntax.
// Expected nodes:
//   - role="user_defined_net_decl" group node (per UserDefinedNetDeclaration
//     statement) carrying the user nettype name; promoted under the
//     enclosing module via ``has_user_defined_net_decl`` edges.
//   - role="net" Declarator children promoted under each group with
//     ``groups_net`` edges from the group + ``has_net`` edges from the
//     enclosing module (same convention as S54).
module user_net_demo;
    nettype real wreal;
    wreal #1 wu1;
    wreal #2 wu2, wu3;
endmodule

// S55 corpus: non-ANSI module with PortDeclarations in the body.
// Module header carries an ImplicitNonAnsiPort list (a, b, c, d, e, f); the
// PortDeclarations in the body bind each name to a direction + type. S55
// promotes each Declarator under a PortDeclarationSyntax as role="port" with
// the direction attribute lifted from the parent header (Variable/Net port
// header). Multiple declarators per PortDeclaration are supported
// (``output e, f``).
module nonansi_demo(a, b, c, d, e, f);
    input  a;
    output [7:0] b;
    inout  wire c;
    input  signed [3:0] d;
    output e, f;
endmodule

// S64 corpus: ANSI module header with ExplicitAnsiPort entries.
// Each ``.name(expr)`` form in the ANSI port list — prefixed with a direction
// keyword — parses as SyntaxKind.ExplicitAnsiPort (sibling of S1's
// ImplicitAnsiPort). The port name is the identifier after the dot; the
// optional connect expression remaps the public name onto an internal signal.
// The empty-connect form ``.pd()`` is legal SV (declares a port with no
// internal connection) and must not crash the rule.
module ansi_explicit_demo(
    input  .pa(x),
    output .pb(y[3:0]),
    inout  .pc(z),
    input  .pd()
);
    wire x, z;
    wire [3:0] y;
endmodule

// S65 corpus: legacy Verilog-2001 non-ANSI explicit port form. Each
// ``.name(expr)`` inside a NonAnsiPortList (no direction keyword in the
// header — directions arrive via separate input/output statements in the
// body) parses as SyntaxKind.ExplicitNonAnsiPort. The explicit empty-connect
// ``.b()`` form is also ExplicitNonAnsiPort (pyslang surfaces it with no
// PortReference child); the bare ``.b`` shorthand is intentionally NOT used
// here because the structural round-trip currently normalises it to
// ``.b()`` — a known pre-existing lift/unlift limitation independent of
// S65. Sibling of S1's ImplicitAnsiPort and S64's ExplicitAnsiPort;
// direction lives on the body PortDeclaration (S55).
module legacy_explicit_demo(.a(p), .b());
    input p, b;
endmodule

// S66 corpus: legacy Verilog-2001 non-ANSI implicit port form. Each bare
// name in the NonAnsiPortList parses as SyntaxKind.ImplicitNonAnsiPort with
// a PortReferenceSyntax child carrying the identifier; directions/types
// arrive via separate input/output statements in the body (S55). The
// concatenation entry ``{x, y}`` parses as ImplicitNonAnsiPort wrapping a
// PortConcatenationSyntax — S66 skips emission for the concatenation form
// (no single port name to key on); S68 promotes the PortConcatenation
// itself as role=port_concat at the synthetic path
// ``legacy_implicit_demo.__port_concat_0__`` and emits groups_port_ref
// edges to its constituent PortReference members (x, y). Sibling of S1
// ImplicitAnsiPort, S64 ExplicitAnsiPort, S65 ExplicitNonAnsiPort.
module legacy_implicit_demo(a, b, {x, y});
    input a;
    output b;
    input x, y;
endmodule

// Out-of-source assertion module bound into `fifo`.
//
// Demonstrates the SystemVerilog `bind` directive: `fifo_asserts` is
// attached to every instance of `fifo` without `fifo.sv` referencing it.
// EDA tools resolve this during elaboration; the AST-experiment promotes
// it to a `bound_into` semantic edge in S13.

module fifo_asserts(
    input logic clk,
    input logic full,
    input logic push
);
    // S39 — default disable condition for all concurrent assertions in this
    // scope. ``rst_n`` is referenced in the iff expression; the rule must
    // emit a ``reads`` edge from the default_disable node to the port.
    logic rst_n;
    default disable iff (!rst_n);

    // Placeholder assertions — body is intentionally empty for the
    // round-trip corpus. The semantic edge is independent of contents.
    // S57 — LocalVariableDeclaration inside property/sequence bodies.
    // pyslang surfaces these as LocalVariableDeclarationSyntax (distinct
    // from procedural-scope DataDeclarationSyntax). Each declarator inside
    // a single ``int a, b;`` form fans out to its own role=local_var node.
    property p_push_implies_not_full;
        int hits = 0;
        bit [7:0] mask, scratch;
        @(posedge clk) push |-> !full;
    endproperty

    sequence s_push_then_full;
        int seen = 0;
        @(posedge clk) push ##[1:2] full;
    endsequence

    // S77 — AssertionItemPort: ports declared on a parameterised property /
    // sequence / let. Each ``input bit clk`` / ``logic sig`` / ``int n``
    // entry parses as an AssertionItemPortSyntax inside the
    // AssertionItemPortListSyntax wrapper. S77 promotes each to role=
    // assertion_item_port with direction/data_type/local/name attrs and a
    // ``has_assertion_item_port`` edge from the enclosing property /
    // sequence / let.
    property p_with_ports(logic sig, int n);
        @(posedge clk) sig |-> ##n !sig;
    endproperty

    sequence s_with_ports(logic a, logic b);
        @(posedge clk) a ##1 b;
    endsequence

    // S77 — port with explicit ``local input`` direction qualifier. Per
    // LRM 16.8, only ``local`` and (for properties) ``input``-style
    // directions are accepted on assertion item ports; ``let`` ports do
    // not allow a direction keyword.
    property p_dir_ports(local input logic sig, logic gate);
        @(posedge clk) gate |-> sig;
    endproperty

    // S18 — clocking blocks. ``cb_fifo`` is an ordinary clocking block;
    // ``cb_default`` exercises the ``default clocking`` form. Clocking items
    // (input/output direction declarations) stay BLOB — only the
    // ClockingDeclaration itself is promoted.
    clocking cb_fifo @(posedge clk);
        input  full, push;
        output #1 rst_n;
    endclocking

    default clocking cb_default @(posedge clk);
        default input #1step output #2;
    endclocking

    // S40 — DefaultClockingReference: ``default clocking <name>;`` selects
    // which named clocking block is the implicit default for the scope.
    // This is an edge-only kind (no independent identity); S40 emits a
    // ``default_clocking`` edge from the enclosing module to the target
    // clocking block. Resolved via name_index; fallback to _unresolved.<name>.
    default clocking cb_fifo;

    // S71 — module-scope immediate assertion. Parses as an
    // ``ImmediateAssertionMember`` wrapping the inner
    // ``ImmediateAssertStatement``; S71 owns the wrapper (stub only) and
    // S17 promotes the inner. Exactly one assertion node must result.
    a_imm_modscope: assert (!(push && full));

    // S16 — concurrent assertion use sites. Labeled top-level forms exercise
    // the ConcurrentAssertionMember wrapper path; the unlabeled cover sits
    // alongside to confirm synthetic-label fallback.
    a_no_push_when_full: assert property (@(posedge clk) full |-> !push);
    a_push_implies_seq: assume property (@(posedge clk) push |-> !full);
    c_push_event: cover property (@(posedge clk) push);
    cover property (@(posedge clk) push |-> !full);

    // S17 — immediate assertions inside a procedural context. Per LRM these
    // cannot sit at module top level (except via the ImmediateAssertionMember
    // wrapper); a labeled + unlabeled + deferred (#0) + deferred (final) +
    // assume + cover form covers the kind grid. We use ``initial`` rather
    // than ``always_comb`` so the corpus does not perturb existing query
    // tests that count always_comb blocks across the multi-file fixture.
    initial begin
        a_imm_no_push_when_full: assert (!(push && full));
        c_imm_push: cover (push);
        a_imm_deferred_zero: assert #0 (!(push && full));
        a_imm_deferred_final: assert final (!(push && full));
        assume (clk === 1'b0 || clk === 1'b1);
    end

    // S22 — covergroup declarations. ``cg_fifo`` carries a clocking event
    // (``@(posedge clk)``); ``cg_simple`` has none. S23 — coverpoint and
    // cross sub-elements are promoted. S41 — CoverageBins declarations inside
    // coverpoints are promoted with role=coverage_bins and bins_kind attr.
    covergroup cg_fifo @(posedge clk);
        cp_full: coverpoint full;
        cp_push: coverpoint push {
            bins low    = {[0:3]};
            bins high[] = {[4:7]};
            illegal_bins bad = {255};
        }
        cp_push_full: coverpoint {push, full};
        cx_push_full: cross cp_push, cp_full;
    endgroup

    covergroup cg_simple;
        cp_full: coverpoint full;
    endgroup
endmodule

// S19 — procedural continuous assign/deassign. These are statement-level
// constructs inside an always block (distinct from S2's module-level
// continuous assign). The corpus must include a writable variable that
// is the target of both forms so the LHS-extraction path is exercised.
module proc_assign_demo (
    input  logic       clk,
    input  logic       load,
    input  logic [7:0] din,
    output logic [7:0] q
);
    logic [7:0] r;
    always @(posedge clk) begin
        if (load) assign r = din;
        else      deassign r;
    end
    assign q = r;
endmodule

// S20 — procedural force/release. Like S19's assign/deassign but stronger:
// `force` overrides even continuous drivers, and `release` lifts the override.
// pyslang surfaces these as ProceduralAssignStatementSyntax /
// ProceduralDeassignStatementSyntax classes — discriminated only by
// SyntaxKind.{ProceduralForceStatement,ProceduralReleaseStatement}.
module force_release_demo (
    input  logic       clk,
    input  logic       dbg_override,
    output logic [7:0] dbg_q
);
    logic [7:0] r;
    always @(posedge clk) begin
        if (dbg_override) force r = 8'hAA;
        else              release r;
    end
    assign dbg_q = r;
endmodule

// S21 — named event trigger statements. ``-> ev`` is the blocking form,
// ``->> ev`` is the nonblocking form. pyslang surfaces both as
// EventTriggerStatementSyntax — discriminated only by SyntaxKind
// {BlockingEventTriggerStatement, NonblockingEventTriggerStatement}.
module event_trigger_demo (input logic clk);
    event ev_done, ev_ready;
    always @(posedge clk) begin
        -> ev_done;
        ->> ev_ready;
    end
endmodule

// S42 — LetDeclaration: compile-time macro-like substitution. ``let nonzero(x)
// = x != 0;`` declares a single-port let that can be used inside assertion
// expressions. The rule promotes it with role=let_decl, a has_let edge from
// the enclosing module, and registers the qualified path in the name_index so
// callers referencing the let can resolve it.
module let_decl_demo (
    input logic clk,
    input logic [7:0] data
);
    let nonzero(x) = x != 0;
    let in_range(a, b) = a < b;
    let always_true() = 1;
    // S77 — let with a default-valued AssertionItemPort. ``let`` ports do
    // not accept a direction keyword (LRM forbids it); the directional
    // case is covered via the parameterised sequence ``s_dir_ports`` in
    // module ``fifo_asserts`` above.
    let bounded(int x, int hi = 8) = x < hi;
endmodule

bind fifo fifo_asserts u_asserts(.clk(clk), .full(full), .push(push));

// S61 — explicit BindTargetList: this bind directive applies only to the
// named instances ``u_fifo_a`` and ``u_fifo_b`` of module ``fifo``, not to
// every instance of ``fifo``. The ``: u_fifo_a, u_fifo_b`` clause is the
// BindTargetListSyntax — a connector child of BindDirective listing the
// specific instance names. ``ghost_u`` exercises the unresolved fallback.
bind fifo : u_fifo_a, u_fifo_b, ghost_u fifo_asserts u_targeted(.clk(clk), .full(full), .push(push));

interface fifo_if #(parameter int WIDTH = 32) (input logic clk, input logic rst_n);
    logic                push, pop, full, empty;
    logic [WIDTH-1:0]    din, dout;
    modport producer (input  full, empty, dout, output push, din);
    modport consumer (input  full, empty, dout, output pop);
    modport dut      (input  push, pop, din, output full, empty, dout);
endinterface

package fifo_pkg;
  typedef enum logic [1:0] { EMPTY = 2'b00, NORMAL = 2'b01, FULL = 2'b10 } fifo_status_e;
  typedef struct packed {
    logic [7:0]  cmd;
    logic [31:0] payload;
    bit [3:0] flag_a, flag_b;
  } fifo_word_t;
  typedef union { int i; bit [31:0] b; } fifo_iu_t;
  typedef fifo_fwd_t;
  typedef enum fifo_fwd_enum_t;
  typedef struct fifo_fwd_struct_t;
  typedef union fifo_fwd_union_t;
  typedef class fifo_fwd_class_t;
  typedef interface class fifo_fwd_iface_class_t;
  parameter int DEFAULT_DEPTH = 8;
  nettype logic [7:0] data_net_t;
  nettype logic [7:0] resolved_net_t with fifo_resolver;
  export *::*;
endpackage

// S86 corpus: InterfacePortHeader — ANSI module ports declared with an
// interface type, optionally modport-qualified.
//
// Exercises three header shapes:
//   1. ``fifo_if.dut a`` — interface name + ``.dut`` modport
//   2. ``fifo_if.consumer b`` — interface name + ``.consumer`` modport
//   3. ``interface c`` — generic ``interface`` keyword form (no name, no
//      modport — InterfacePortHeader with the InterfaceKeyword variant).
//
// The leaf module body is empty on purpose: the port headers are the only
// semantic content S86 needs.

module iface_port_dut (
    fifo_if.dut       a,
    fifo_if.consumer  b,
    interface         c
);
endmodule

// S33 corpus: gate-level primitive instantiations.
//
// Covers four primitive types (and / or / buf with delay / not in
// multi-instance form). Mirrors how UDP-free RTL hand-instantiates
// gates at the leaf of a hierarchy.
module prim_demo (
    input  logic a,
    input  logic b,
    output logic out_and,
    output logic out_or,
    output logic out_buf,
    output logic n_a,
    output logic n_b
);
  and g_and (out_and, a, b);
  or  g_or  (out_or, a, b);
  buf #5 g_buf (out_buf, a);
  not g_not1 (n_a, a), g_not2 (n_b, b);
endmodule

// S81 corpus: extern primitive declarations (UDP prototypes).
//
// Two forms are exercised: the non-ansi bare-identifier port list, and
// the ansi typed port-decl form. Both prototype-only — the UDP bodies
// would live in separate `primitive ... endprimitive` blocks elsewhere
// in the compilation (out-of-scope here).
extern primitive my_ext_prim_nonansi (out_p, in_p1, in_p2);
extern primitive my_ext_prim_ansi (output reg q, input d, input clk);

module tb_fifo;
    logic        clk;
    logic        rst_n;
    logic        push;
    logic        pop;
    logic [31:0] din;
    logic [31:0] dout;
    logic        full;
    logic        empty;
    logic        push_a;
    logic        pop_a;
    logic [31:0] din_a;
    logic [31:0] dout_a;
    logic        full_a;
    logic        empty_a;
    logic        push_b;
    logic        pop_b;
    logic [7:0]  din_b;
    logic [7:0]  dout_b;
    logic        full_b;
    logic        empty_b;

    top u_dut (
        .clk    (clk),
        .rst_n  (rst_n),
        .push   (push),
        .pop    (pop),
        .din    (din),
        .dout   (dout),
        .full   (full),
        .empty  (empty),
        .push_a (push_a),
        .pop_a  (pop_a),
        .din_a  (din_a),
        .dout_a (dout_a),
        .full_a (full_a),
        .empty_a(empty_a),
        .push_b (push_b),
        .pop_b  (pop_b),
        .din_b  (din_b),
        .dout_b (dout_b),
        .full_b (full_b),
        .empty_b(empty_b)
    );

    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    initial begin
        rst_n = 0;
        push  = 0;
        pop   = 0;
        din   = 32'h0;
        #20 rst_n = 1;
        #10 push = 1; din = 32'hCAFEBABE;
        #10 push = 0;
        #10 pop  = 1;
        #10 pop  = 0;
        $display("dout=%h full=%b empty=%b", dout, full, empty);
        #20 $finish;
    end

    integer err_count;
    final begin
        $display("done: count=%0d", err_count);
    end

